  "subject": "❌ Your listing needs changes — NIRVANA MART",
  "html": "<div style='font-family:Segoe UI,sans-serif;max-width:600px;margin:0 auto;background:#f5f5f5;padding:24px;border-radius:12px;'><div style='background:linear-gradient(135deg,#ef4444,#dc2626);padding:28px;border-radius:10px;text-align:center;margin-bottom:24px;'><div style='font-size:3rem;margin-bottom:8px;'>⚠️</div><h1 style='color:white;margin:0;font-size:1.3rem;'>Listing Needs Revision</h1></div><div style='background:white;padding:24px;border-radius:10px;margin-bottom:20px;'><p style='color:#333;'>Hi <strong>{{ $('Webhook: Product Status Changed').first().json.body.seller_name }}</strong>,</p><p style='color:#555;line-height:1.7;'>Your listing <strong>{{ $('Webhook: Product Status Changed').first().json.body.product_title }}</strong> was not approved for the following reason:</p><div style='background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:16px;margin:16px 0;'><p style='color:#dc2626;margin:0;font-weight:600;'>{{ $('Webhook: Product Status Changed').first().json.body.rejection_reason || 'Does not meet our listing guidelines. Please review and relist.' }}</p></div><p style='color:#555;'>Please update your listing and resubmit. Common issues:</p><ul style='color:#555;line-height:1.8;'><li>Unclear or low-quality product image</li><li>Price is unreasonably high or low</li><li>Description is too short or misleading</li><li>Item not suitable for campus marketplace</li></ul></div><div style='text-align:center;'><a href='https://nirvana-mart.onrender.com/seller.html' style='display:inline-block;background:#c8923a;color:white;padding:14px 32px;border-radius:8px;text-decoration:none;font-weight:700;'>Edit and Relist →</a></div><p style='color:#aaa;font-size:0.78rem;text-align:center;margin-top:20px;'>NIRVANA MART — Campus Marketplace</p></div>"
}
